normalSourceSnippets.nextListbox:
'use client';
import { useState } from 'react';
const options = ['Alpha', 'Beta'];
export function Listbox() {
  const [selected, setSelected] = useState(0);
  function onKeyDown(event: React.KeyboardEvent<HTMLUListElement>) {
    if (event.key === 'ArrowDown') setSelected((index) => Math.min(index + 1, options.length - 1));
    if (event.key === 'ArrowUp') setSelected((index) => Math.max(index - 1, 0));
  }
  return (
    <ul
      role="listbox"
      aria-label="Choices"
      tabIndex={0}
      aria-activedescendant={`choice-${selected}`}
      onKeyDown={onKeyDown}
    >
      {options.map((label, index) => (
        <li
          id={`choice-${index}`}
          role="option"
          aria-selected={selected === index}
          key={label}
        >
          {label}
        </li>
      ))}
    </ul>
  );
}

